//
// Typed SQL helpers — bridge between raw STDB SQL responses (positional arrays)
// and properly typed objects using the auto-generated module_bindings schemas.
//
// The module_bindings directory contains row schemas generated by `spacetime
// generate` from the Rust module. Each table schema (e.g. `page_table.ts`)
// exports a row definition via `__t.row({...})`.
//
// This module provides a `fromStdbRow` utility that introspects the module_binding
// schema at runtime to automatically convert positional row arrays from STDB's
// HTTP SQL API into properly typed JavaScript objects — without needing the
// manual `mappers.ts` functions.
//
// Usage:
//   import { fromStdbRow } from "./typed-sql";
//   import PageRowSchema from "../../module_bindings/page_table";
//   const rows = await sqlQuery("SELECT * FROM page");
//   const pages = rows.map(fromStdbRow(PageRowSchema));
//
// Long-term goal: Replace raw SQL + manual mappers with the SDK's typed
// subscription system (DbConnection + query builders).

import type { Infer as __Infer } from 'spacetimedb';

