// ─── Internal: element descriptor cache ────────────────────────────────
// Each schema's field order is resolved once (lazily) and cached.

type FieldDescriptor = {
  name: string;
  tag: string;
  coerce: (v: unknown) => unknown;
};

const elementCache = new WeakMap<object, FieldDescriptor[]>();

function getElements(schema: object): FieldDescriptor[] {
  const cached = elementCache.get(schema);
  if (cached) return cached;
  const s = schema as Record<string, unknown>;
  const elements = ((s.algebraicType as Record<string, unknown>)?.value as Record<string, unknown>)
    ?.elements as Array<Record<string, unknown>> | undefined;
  if (!Array.isArray(elements)) {
    throw new Error('fromStdbRow: schema does not expose algebraicType.value.elements');
  }
  const rowDef = s.row as Record<string, unknown> | undefined;
  const descs: FieldDescriptor[] = elements.map((el) => {
    const jsName = el.name as string;
    // Use the DB column name (from columnMetadata.name) if available,
    // otherwise fall back to the JS field name. This produces snake_case
    // keys matching the existing types.ts interfaces.
    const colMeta = rowDef?.[jsName] as Record<string, unknown> | undefined;
    const dbName =
      ((colMeta?.columnMetadata as Record<string, unknown> | undefined)?.name as string) ?? jsName;
    const tag = (el.algebraicType as Record<string, unknown>)?.tag as string;
    let coerce: (v: unknown) => unknown;
    switch (tag) {
      case 'String':
        coerce = (v: unknown) => (v ?? '') as string;
        break;
      case 'Bool':
        coerce = (v: unknown) => Boolean(v);
        break;
      case 'U32':
      case 'U64':
      case 'I32':
      case 'I64':
      case 'F32':
      case 'F64':
        coerce = (v: unknown) => Number(v) || 0;
        break;
      default:
        coerce = (v: unknown) => v as unknown;
        break; // arrays, tables, etc.
    }
    return { name: dbName, tag, coerce };
  });
  elementCache.set(schema, descs);
  return descs;
}

// ─── fromStdbRow ───────────────────────────────────────────────────────
// Converts a positional row array from STDB's HTTP SQL API into a typed
// object using the auto-generated module_binding row schema.
//
// The schema's `algebraicType.value.elements` array defines field order,
// which matches `SELECT *` column order from STDB.
//
// Usage:
//   const rows = await sqlQuery("SELECT * FROM page");
//   const pages = rows.map(fromStdbRow(PageRowSchema));
//   // pages: StdbPage[] (camelCase fields matching module_bindings)

export function fromStdbRow<T>(schema: object & { __isRowSchema?: never }): (row: unknown[]) => T {
  const fields = getElements(schema);
  return (row: unknown[]): T => {
    const obj: Record<string, unknown> = {};
    const len = Math.min(fields.length, row.length);
    for (let i = 0; i < len; i++) {
      obj[fields[i].name] = fields[i].coerce(row[i]);
    }
    return obj as T;
  };
}
